#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_SESSIONS 64
#define TOKEN_LEN 32
#define MAX_MSG_SIZE 4096

typedef struct {
    uint8_t  active;
    uint8_t  privilege;  /* 0=user, 1=admin */
    uint32_t uid;
    char     token[TOKEN_LEN];
    char     username[64];
} session_t;

typedef struct {
    uint8_t  opcode;
    uint8_t  flags;
    uint16_t payload_len;
    char     token[TOKEN_LEN];
    char     payload[MAX_MSG_SIZE];
} request_t;

static session_t sessions[MAX_SESSIONS];
static pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

static void generate_token(char *buf) {
    FILE *f = fopen("/dev/urandom", "r");
    if (f) { fread(buf, 1, TOKEN_LEN, f); fclose(f); }
}

static int find_session(const char *token) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].active &&
            memcmp(sessions[i].token, token, TOKEN_LEN) == 0)
            return i;
    }
    return -1;
}

static int create_session(const char *username, uint32_t uid, uint8_t priv) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!sessions[i].active) {
            sessions[i].active = 1;
            sessions[i].privilege = priv;
            sessions[i].uid = uid;
            strncpy(sessions[i].username, username, 63);
            sessions[i].username[63] = '\0';
            generate_token(sessions[i].token);
            pthread_mutex_unlock(&session_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return -1;
}

/* Authenticate user - returns session index or -1 */
static int authenticate(const char *username, const char *password) {
    /* Simplified: accept any user with password "valid" */
    if (strcmp(password, "valid") == 0) {
        uint8_t priv = (strcmp(username, "admin") == 0) ? 1 : 0;
        return create_session(username, 1000, priv);
    }
    return -1;
}

/* Check if the request's session has admin privilege */
static int check_admin(const char *token) {
    int idx = find_session(token);
    if (idx < 0) return 0;
    return sessions[idx].privilege == 1;
}

/* Lookup session and return privilege level for authorization */
static int get_privilege(const char *token) {
    int idx = find_session(token);
    if (idx < 0) return -1;
    return (int)sessions[idx].privilege;
}

/*
 * Process admin command - should only be callable by admins.
 * Executes privileged operations on the system.
 */
static int process_admin_cmd(int client_fd, const char *payload, uint16_t len) {
    /* Admin-only: read arbitrary file */
    char filepath[256];
    if (len >= sizeof(filepath)) len = sizeof(filepath) - 1;
    memcpy(filepath, payload, len);
    filepath[len] = '\0';

    /* Sanitize path - no directory traversal */
    if (strstr(filepath, "..") != NULL) {
        send(client_fd, "ERR:TRAVERSAL\n", 14, 0);
        return -1;
    }

    char fullpath[512];
    snprintf(fullpath, sizeof(fullpath), "/var/app/data/%s", filepath);

    FILE *f = fopen(fullpath, "r");
    if (!f) {
        send(client_fd, "ERR:NOFILE\n", 11, 0);
        return -1;
    }
    char buf[4096];
    size_t n = fread(buf, 1, sizeof(buf) - 1, f);
    buf[n] = '\0';
    fclose(f);
    send(client_fd, buf, n, 0);
    return 0;
}

/* Process user profile update */
static int process_profile_update(int client_fd, const char *token,
                                   const char *payload, uint16_t len) {
    int idx = find_session(token);
    if (idx < 0) return -1;

    /* Parse "field=value" from payload */
    char field[64], value[256];
    const char *eq = memchr(payload, '=', len);
    if (!eq) return -1;

    size_t flen = eq - payload;
    if (flen >= sizeof(field)) return -1;
    memcpy(field, payload, flen);
    field[flen] = '\0';

    size_t vlen = len - flen - 1;
    if (vlen >= sizeof(value)) vlen = sizeof(value) - 1;
    memcpy(value, eq + 1, vlen);
    value[vlen] = '\0';

    if (strcmp(field, "username") == 0) {
        pthread_mutex_lock(&session_lock);
        strncpy(sessions[idx].username, value, 63);
        sessions[idx].username[63] = '\0';
        pthread_mutex_unlock(&session_lock);
    }

    send(client_fd, "OK\n", 3, 0);
    return 0;
}

/*
 * Main request dispatcher.
 * Opcodes:
 *   0x01 = login (payload: "user:pass")
 *   0x02 = admin command (requires admin)
 *   0x03 = profile update
 *   0x04 = logout
 */
static void handle_request(int client_fd, request_t *req) {
    switch (req->opcode) {
    case 0x01: { /* Login */
        char *colon = memchr(req->payload, ':', req->payload_len);
        if (!colon) { send(client_fd, "ERR:FORMAT\n", 11, 0); return; }
        *colon = '\0';
        char *user = req->payload;
        char *pass = colon + 1;
        int sess = authenticate(user, pass);
        if (sess >= 0) {
            char resp[TOKEN_LEN + 4];
            memcpy(resp, "OK:", 3);
            memcpy(resp + 3, sessions[sess].token, TOKEN_LEN);
            resp[TOKEN_LEN + 3] = '\n';
            send(client_fd, resp, TOKEN_LEN + 4, 0);
        } else {
            send(client_fd, "ERR:AUTH\n", 9, 0);
        }
        break;
    }
    case 0x02: { /* Admin command */
        int priv = get_privilege(req->token);
        /* Authorization check: verify admin privilege */
        if (priv < 1) {
            send(client_fd, "ERR:DENIED\n", 11, 0);
            return;
        }
        process_admin_cmd(client_fd, req->payload, req->payload_len);
        break;
    }
    case 0x03: { /* Profile update */
        int idx = find_session(req->token);
        if (idx < 0) { send(client_fd, "ERR:SESSION\n", 12, 0); return; }
        process_profile_update(client_fd, req->token, req->payload, req->payload_len);
        break;
    }
    case 0x04: { /* Logout */
        int idx = find_session(req->token);
        if (idx >= 0) {
            pthread_mutex_lock(&session_lock);
            sessions[idx].active = 0;
            memset(&sessions[idx], 0, sizeof(session_t));
            pthread_mutex_unlock(&session_lock);
        }
        send(client_fd, "OK\n", 3, 0);
        break;
    }
    default:
        send(client_fd, "ERR:OPCODE\n", 11, 0);
    }
}

static void *client_handler(void *arg) {
    int fd = *(int *)arg;
    free(arg);

    while (1) {
        request_t req;
        memset(&req, 0, sizeof(req));

        /* Read header: opcode(1) + flags(1) + payload_len(2) + token(32) = 36 bytes */
        uint8_t hdr[36];
        ssize_t n = recv(fd, hdr, 36, MSG_WAITALL);
        if (n != 36) break;

        req.opcode = hdr[0];
        req.flags = hdr[1];
        req.payload_len = ntohs(*(uint16_t *)(hdr + 2));
        memcpy(req.token, hdr + 4, TOKEN_LEN);

        if (req.payload_len > MAX_MSG_SIZE) {
            send(fd, "ERR:SIZE\n", 9, 0);
            break;
        }

        if (req.payload_len > 0) {
            n = recv(fd, req.payload, req.payload_len, MSG_WAITALL);
            if (n != req.payload_len) break;
        }

        handle_request(fd, &req);
    }

    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int port = argc > 1 ? atoi(argv[1]) : 8080;
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    bind(srv, (struct sockaddr *)&addr, sizeof(addr));
    listen(srv, 16);

    while (1) {
        int *cfd = malloc(sizeof(int));
        *cfd = accept(srv, NULL, NULL);
        if (*cfd < 0) { free(cfd); continue; }
        pthread_t t;
        pthread_create(&t, NULL, client_handler, cfd);
        pthread_detach(t);
    }
    return 0;
}
